/* Minimal offline navbar collapse support compatible with Bootstrap data attributes. */
(function(){'use strict';document.addEventListener('click',function(e){var btn=e.target.closest('[data-bs-toggle="collapse"]');if(!btn)return;var selector=btn.getAttribute('data-bs-target')||btn.getAttribute('href');if(!selector)return;var target=document.querySelector(selector);if(!target)return;var isOpen=target.classList.toggle('show');btn.setAttribute('aria-expanded',isOpen?'true':'false');});})();
